// ==UserScript==
// @name         TrollModPoke
// @namespace    trollmodpoke
// @version      1.0
// @description  TrollModPoke APK (base64)
// @match        *://*/*
// @grant        none
// ==/UserScript==

// TrollModPoke.apk encoded as base64
const TrollModPokeBase64 = "";

// Decode to Uint8Array (browser/Node)
function getApkBytes() {
  if (typeof Buffer !== "undefined") return new Uint8Array(Buffer.from(TrollModPokeBase64, "base64"));
  const bin = atob(TrollModPokeBase64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

if (typeof module !== "undefined") module.exports = { TrollModPokeBase64, getApkBytes };
